//! `gpud` client (docs/kabylake-gpu-plan.md, stage G1): the display state the
//! Intel GPU service adopted from the firmware.
//!
//! The `os.lazy.gpu.v1` stubs are generated by `midlc` from `idl/gpu.midl`;
//! this module adds the service name, the reply framing and a blocking
//! [`Client`]. The service failure convention is the shared structured error
//! field ([`super::services::error_field`]).

use alloc::vec::Vec;

use libmessenger::{Header, Parcel, VERSION};

use super::services::error_field;
use super::{registry, Endpoint, Error, Result};

/// The generated `os.lazy.gpu.v1` stubs.
pub use messenger_generated::os_lazy_gpu_v1 as wire;

/// The adopted display state.
pub use wire::State;

/// Registered service name.
pub const NAME: &str = "os.lazy.gpu";

/// The interface id every `gpud` parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// A parcel of `method` carrying an already-encoded `body` (request or reply).
pub fn parcel(method: u32, body: Vec<u8>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: INTERFACE,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        ..Parcel::default()
    }
}

/// A blocking client of `gpud`.
pub struct Client {
    endpoint: Endpoint,
}

impl Client {
    /// Resolve [`NAME`]; the endpoint is opened in this task's handle table.
    pub fn connect() -> Result<Client> {
        Ok(Client {
            endpoint: registry::resolve(NAME)?,
        })
    }

    /// The display state `gpud` adopted.
    pub fn state(&self) -> Result<State> {
        let reply = self
            .endpoint
            .call(&parcel(wire::METHOD_GETSTATE, Vec::new()), None)?;
        if let Some(code) = error_field(&reply)? {
            return Err(Error::Errno(-code));
        }
        Ok(wire::decode_get_state_reply(&reply.body)
            .map_err(Error::Parcel)?
            .state)
    }
}
